// Generator v2 ("progressive difficulty"), used for every NEW session (game_sessions.gen_version = 2).
// Sessions created before v1.2.x keep gen_version NULL/1 and are regenerated by the untouched v1 code in generate.ts,
// so resuming an old session or re-scoring it never changes its questions.
//
// What changes compared with v1:
//  * the grade/age band is centred on the real grade (grade 6 is NOT "upper band" any more, see tuningForV2);
//  * inside one pool the difficulty RISES SMOOTHLY with the item position (no sudden jump at the end);
//  * hard limits so "advanced" stays solvable: memory ≤ 7 items, reverse recall only on the shortest sequences,
//    attention grid ≤ 5×5 with generous time, problem-solving never borrows UPWARD before borrowing downward.
import { makeRng, randInt, shuffle } from '../utils/rng';
import { PROBLEM_BANK, type ProblemQuestion } from './bank';
import { isValidProblem } from './validate';
import type { Tuning } from './generate';

export const GEN_VERSION = 2;
const SYMBOLS = ['red', 'blue', 'green', 'yellow', 'star', 'moon', 'heart', 'sun', 'triangle'];
const COLORS = ['red', 'blue', 'green', 'yellow'];

type Level = 1 | 2 | 3;
const k = (t: Tuning) => String(t) as '-1' | '0' | '1';
/** Linear ramp from lo (first item) to hi (last item). */
export const ramp = (i: number, count: number, lo: number, hi: number) => (count <= 1 ? lo : lo + Math.round(((hi - lo) * i) / (count - 1)));

/** Items to remember [first level][min,max]. Hard ceiling 7 (children's visual-sequence span); only 9 symbols exist. */
export const MEMORY_RANGES = { '-1': [[2, 3], [3, 4], [4, 5]], '0': [[3, 4], [4, 5], [5, 6]], '1': [[3, 5], [4, 6], [5, 7]] } as const;
/** Milliseconds each item is shown. */
export const MEMORY_DURATIONS = { '-1': [2000, 1700, 1500], '0': [1500, 1300, 1100], '1': [1300, 1150, 1000] } as const;

export function memoryQuestionsV2(seed: string, difficulty: Level, count: number, tuning: Tuning = 0) {
  const rng = makeRng(`${seed}:mem:${difficulty}`);
  const [lo, hi] = MEMORY_RANGES[k(tuning)][difficulty - 1];
  const duration = MEMORY_DURATIONS[k(tuning)][difficulty - 1];
  const seen = new Set<string>();
  const out = [];
  for (let i = 0; i < count; i++) {
    const len = ramp(i, count, lo, hi);
    let seq: string[] = [];
    for (let tries = 0; tries < 30; tries++) {
      seq = shuffle(SYMBOLS, rng).slice(0, len);
      if (!seen.has(seq.join(','))) break;
    }
    seen.add(seq.join(','));
    const flip = rng();
    out.push({
      id: `mem_${difficulty}_${i + 1}`, game: 'memory' as const, type: 'sequence', difficulty,
      sequence: seq, displayDuration: duration,
      // Reverse recall: level 3 only, never for the youngest band, and only on the shortest sequences of the pool.
      isReverse: difficulty === 3 && tuning !== -1 && len <= lo && flip < 0.5,
      version: 1,
    });
  }
  return out;
}

export const ATTENTION_GRID = { '-1': [3, 3, 3], '0': [3, 4, 4], '1': [4, 4, 5] } as const;
export const ATTENTION_TIME = { '-1': [12000, 10000, 9000], '0': [8000, 7000, 6500], '1': [7000, 6000, 5500] } as const;

export function attentionQuestionsV2(seed: string, difficulty: Level, count: number, tuning: Tuning = 0) {
  const rng = makeRng(`${seed}:att:${difficulty}`);
  const grid = ATTENTION_GRID[k(tuning)][difficulty - 1];
  const maxTargets = grid; // 3×3 → up to 3 targets, 4×4 → 4, 5×5 → 5
  const timeLimit = ATTENTION_TIME[k(tuning)][difficulty - 1];
  const cellsN = grid * grid;
  const changeAt = difficulty === 3 ? Math.max(2, Math.floor(count / 2)) : -1;
  const out = [];
  for (let i = 0; i < count; i++) {
    const changed = changeAt >= 0 && i >= changeAt;
    const select = difficulty === 3 ? (changed ? 'red' : 'blue') : COLORS[randInt(rng, 0, 3)];
    const avoid = difficulty === 3 ? (changed ? 'blue' : 'red') : null;
    // The number of targets to find grows steadily with the item position.
    const upper = ramp(i, count, 2, maxTargets);
    const lower = ramp(i, count, 2, Math.max(2, maxTargets - 1));
    const targetCount = randInt(rng, Math.min(lower, upper), upper);
    const avoidCount = avoid ? randInt(rng, 2, 3) : 0;
    const others = COLORS.filter((c) => c !== select && c !== avoid);
    const cells: string[] = [...Array(targetCount).fill(select), ...Array(avoidCount).fill(avoid)];
    while (cells.length < cellsN) cells.push(others[randInt(rng, 0, others.length - 1)]);
    out.push({
      id: `att_${difficulty}_${i + 1}`, game: 'attention' as const, type: 'grid', difficulty,
      gridSize: grid, cells: shuffle(cells, rng), rule: { select, avoid }, targetCount,
      ruleChanged: changed, phase: difficulty === 3 ? (changed ? 'after' : 'before') : 'none',
      timeLimit, version: 1,
    });
  }
  return out;
}

/** 0 = one-rule/simple, 1 = pattern, 2 = multi-step. */
export const problemComplexity = (q: Pick<ProblemQuestion, 'type'>) => (q.type === 'multi_step' ? 2 : q.type === 'pattern' ? 1 : 0);

export function problemQuestionsV2(seed: string, difficulty: Level, count: number, borrow: boolean, tuning: Tuning = 0) {
  const rng = makeRng(`${seed}:prob:${difficulty}`);
  const valid = PROBLEM_BANK.filter(isValidProblem);
  // Borrow DOWNWARD first (easier fillers), upward only if the bank has nothing else.
  const lower = [1, 2, 3].filter((d) => d < difficulty).reverse();
  const higher = [1, 2, 3].filter((d) => d > difficulty);
  const order = borrow ? [difficulty, ...lower, ...higher] : [difficulty];
  const picked: ProblemQuestion[] = [];
  for (const d of order) {
    const level = shuffle(valid.filter((x) => x.difficulty === d), rng);
    // Younger band takes the simplest items first, older band the more complex ones first (only decides WHICH items are used).
    if (tuning === -1) level.sort((a, b) => problemComplexity(a) - problemComplexity(b));
    else if (tuning === 1) level.sort((a, b) => problemComplexity(b) - problemComplexity(a));
    for (const q of level) { if (picked.length >= count) break; picked.push(q); }
  }
  // Presentation order = a ramp: lower bank level first, then simple → pattern → multi-step.
  picked.sort((a, b) => a.difficulty - b.difficulty || problemComplexity(a) - problemComplexity(b));
  return picked.map((q) => {
    const idx = shuffle(q.options.map((_, i) => i), rng);
    return { ...q, options: idx.map((i) => q.options[i]), correctOption: idx.indexOf(q.correctOption) };
  });
}
